/**
 * Check for pre-known file failures before routing to target system.
 * These are files marked by Classify attachments as skipped
 * (oversized, non_transferable, cim_not_implemented).
 *
 * Patches payload.text with notice and emits notification on output 2.
 * Removes skipped files from payload so target system gets clean entry.
 *
 * Output 1: msg continues (always)
 * Output 2: notification payload (only when pre-known failures exist)
 */
const entry   = msg.entry;
const files   = (entry && entry.files) || [];
const skipped = files.filter(f => f.skipped);

if (skipped.length === 0) return [msg, null];

const succeeded = files.filter(f => !f.skipped).length;
const total     = files.length;

// Patch text notice so target system receives it
const notice = " [" + skipped.length + "/" + total + " vedlegg ikke overført. Avsender mottar instruks om alternativ håndtering]"
msg.payload.text = (msg.payload.text || "") + notice;

// Remove skipped files from payload
msg.payload.files = (msg.payload.files || []).filter(f => !f.skipped);

// Determine notification type
const has_oversized        = skipped.some(f => f.reason === "oversized");
const has_non_transferable = skipped.some(f => f.reason === "non_transferable");

let type = "upload_failed";
if (has_non_transferable && !has_oversized) type = "non_transferable";
else if (has_oversized && !has_non_transferable) type = "oversized_files";

const notification = {
    payload: {
        type,
        entry_id:     entry.id,
        file_names:   skipped.map(f => f.name || "ukjent fil"),
        file_count:   skipped.length,
        total_files:  total,
        succeeded,
        entry_author: entry.author,
        metadata:     msg.metadata
    }
};

return [msg, notification];
